"""Legacy-compatible integration retry wrapper."""

from typing import Any, Callable


class TransientError(Exception):
    """A retryable transport failure."""


class PermanentError(Exception):
    """A non-retryable transport failure."""


def call_with_retry(endpoint_cfg: dict, transport: Callable[[str, int], Any]) -> dict:
    """Invoke an injected transport using the legacy retry-count convention."""
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    max_attempts = endpoint_cfg["retry"] + 1

    attempts = 0

    for _ in range(max_attempts):
        attempts += 1
        try:
            result = transport(url, timeout_ms)
        except TransientError as exc:
            if attempts == max_attempts:
                return {
                    "ok": False,
                    "attempts": attempts,
                    "result": None,
                    "error": {
                        "type": "transient",
                        "message": str(exc),
                    },
                }
        except PermanentError as exc:
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(exc),
                },
            }
        else:
            return {
                "ok": True,
                "attempts": attempts,
                "result": result,
                "error": None,
            }

    raise RuntimeError("retry count must permit at least one attempt")
